/**
 * Chart.js Lightweight Standalone Implementation (MIT License Compatible)
 * Self-hosted for 100% offline execution. Implements Line & Bar charts with
 * high-DPI scaling, smooth curves, legends, and mobile-friendly touch tooltips.
 */
(function (global, factory) {
  typeof exports === 'object' && typeof module !== 'undefined' ? module.exports = factory() :
  typeof define === 'function' && define.amd ? define(factory) :
  (global = typeof globalThis !== 'undefined' ? globalThis : global || self, global.Chart = factory());
})(this, (function () {
  'use strict';

  class Chart {
    constructor(ctxOrCanvas, config) {
      if (typeof ctxOrCanvas === 'string') {
        this.canvas = document.getElementById(ctxOrCanvas);
      } else if (ctxOrCanvas && ctxOrCanvas.getContext) {
        this.canvas = ctxOrCanvas;
      } else if (ctxOrCanvas && ctxOrCanvas.canvas) {
        this.canvas = ctxOrCanvas.canvas;
      } else {
        throw new Error('Invalid canvas element');
      }

      this.ctx = this.canvas.getContext('2d');
      this.config = config || {};
      this.type = this.config.type || 'line';
      this.data = this.config.data || { labels: [], datasets: [] };
      this.options = this.config.options || {};
      this.activeTooltip = null;

      this.initEvents();
      this.render();
    }

    initEvents() {
      this._handleMouseMove = (e) => {
        const rect = this.canvas.getBoundingClientRect();
        const x = e.clientX - rect.left;
        const y = e.clientY - rect.top;
        this.checkHover(x, y);
      };

      this._handleMouseLeave = () => {
        if (this.activeTooltip) {
          this.activeTooltip = null;
          this.render();
        }
      };

      this.canvas.addEventListener('mousemove', this._handleMouseMove);
      this.canvas.addEventListener('mouseleave', this._handleMouseLeave);
      this.canvas.addEventListener('touchmove', (e) => {
        if (e.touches.length > 0) {
          const rect = this.canvas.getBoundingClientRect();
          const x = e.touches[0].clientX - rect.left;
          const y = e.touches[0].clientY - rect.top;
          this.checkHover(x, y);
        }
      }, { passive: true });

      // Resize handling
      if (window.ResizeObserver) {
        this._resizeObserver = new ResizeObserver(() => {
          this.render();
        });
        if (this.canvas.parentElement) {
          this._resizeObserver.observe(this.canvas.parentElement);
        }
      }
    }

    destroy() {
      this.canvas.removeEventListener('mousemove', this._handleMouseMove);
      this.canvas.removeEventListener('mouseleave', this._handleMouseLeave);
      if (this._resizeObserver) {
        this._resizeObserver.disconnect();
      }
      this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height);
    }

    update() {
      this.render();
    }

    checkHover(mouseX, mouseY) {
      if (!this._points || this._points.length === 0) return;
      let closest = null;
      let minDistance = 28;

      for (const p of this._points) {
        const d = Math.hypot(p.x - mouseX, p.y - mouseY);
        if (d < minDistance) {
          minDistance = d;
          closest = p;
        }
      }

      if (closest !== this.activeTooltip) {
        this.activeTooltip = closest;
        this.render();
      }
    }

    render() {
      const canvas = this.canvas;
      const ctx = this.ctx;
      const dpr = window.devicePixelRatio || 1;

      // Handle responsive dimensions
      const rect = canvas.getBoundingClientRect();
      const width = rect.width > 0 ? rect.width : (canvas.parentElement ? canvas.parentElement.clientWidth : 400);
      const height = rect.height > 0 ? rect.height : (canvas.parentElement ? canvas.parentElement.clientHeight : 250);

      canvas.width = Math.max(width * dpr, 200 * dpr);
      canvas.height = Math.max(height * dpr, 150 * dpr);
      ctx.resetTransform ? ctx.resetTransform() : ctx.setTransform(1, 0, 0, 1, 0, 0);
      ctx.scale(dpr, dpr);

      const w = width;
      const h = height;
      ctx.clearRect(0, 0, w, h);

      const labels = this.data.labels || [];
      const datasets = this.data.datasets || [];
      if (labels.length === 0 || datasets.length === 0) {
        ctx.fillStyle = '#94a3b8';
        ctx.font = '13px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText('Aucune donnée disponible', w / 2, h / 2);
        return;
      }

      const padLeft = 45;
      const padRight = 20;
      const padTop = 35;
      const padBottom = 35;
      const plotW = w - padLeft - padRight;
      const plotH = h - padTop - padBottom;

      // Compute max value
      let maxVal = 0;
      let minVal = 0;
      datasets.forEach(ds => {
        (ds.data || []).forEach(val => {
          const v = Number(val) || 0;
          if (v > maxVal) maxVal = v;
          if (v < minVal) minVal = v;
        });
      });

      if (maxVal === 0 && minVal === 0) maxVal = 10;
      maxVal = Math.ceil(maxVal * 1.15);
      if (maxVal < 4) maxVal = 4;

      // Draw Grid & Y-Axis
      ctx.strokeStyle = '#e2e8f0';
      ctx.lineWidth = 1;
      ctx.fillStyle = '#64748b';
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'right';

      const ySteps = 4;
      for (let i = 0; i <= ySteps; i++) {
        const yVal = Math.round((maxVal / ySteps) * i);
        const yPos = padTop + plotH - (plotH / ySteps) * i;

        ctx.beginPath();
        ctx.moveTo(padLeft, yPos);
        ctx.lineTo(w - padRight, yPos);
        ctx.stroke();

        ctx.fillText(yVal, padLeft - 8, yPos + 4);
      }

      // Draw X-Axis Labels
      ctx.textAlign = 'center';
      const stepX = labels.length > 1 ? plotW / (labels.length - 1) : plotW / 2;
      this._points = [];

      labels.forEach((lbl, idx) => {
        const xPos = labels.length > 1 ? padLeft + idx * stepX : padLeft + plotW / 2;
        ctx.fillStyle = '#64748b';
        ctx.fillText(lbl, xPos, h - 12);
      });

      // Draw Datasets
      if (this.type === 'bar') {
        const numDs = datasets.length;
        const groupW = labels.length > 1 ? (plotW / labels.length) * 0.75 : plotW * 0.4;
        const barW = Math.max(groupW / numDs, 6);

        labels.forEach((lbl, labelIdx) => {
          const groupCenter = padLeft + (labelIdx + 0.5) * (plotW / labels.length);
          const startX = groupCenter - (numDs * barW) / 2;

          datasets.forEach((ds, dsIdx) => {
            const val = Number((ds.data || [])[labelIdx]) || 0;
            const barH = (val / maxVal) * plotH;
            const bX = startX + dsIdx * barW;
            const bY = padTop + plotH - barH;

            ctx.fillStyle = ds.backgroundColor || '#3b82f6';
            ctx.beginPath();
            ctx.roundRect ? ctx.roundRect(bX + 1, bY, barW - 2, barH, [4, 4, 0, 0]) : ctx.rect(bX + 1, bY, barW - 2, barH);
            ctx.fill();

            this._points.push({
              x: bX + barW / 2,
              y: bY,
              label: lbl,
              datasetLabel: ds.label || '',
              value: val,
              color: ds.backgroundColor || '#3b82f6'
            });
          });
        });
      } else {
        // Line Chart
        datasets.forEach((ds) => {
          const color = ds.borderColor || '#2563eb';
          const bgColor = ds.backgroundColor || 'rgba(37, 99, 235, 0.1)';
          const data = ds.data || [];
          if (data.length === 0) return;

          const pts = data.map((val, idx) => {
            const x = labels.length > 1 ? padLeft + idx * stepX : padLeft + plotW / 2;
            const y = padTop + plotH - ((Number(val) || 0) / maxVal) * plotH;
            return { x, y, value: val, label: labels[idx], datasetLabel: ds.label || '', color };
          });

          // Fill area under curve
          ctx.beginPath();
          ctx.moveTo(pts[0].x, padTop + plotH);
          pts.forEach(p => ctx.lineTo(p.x, p.y));
          ctx.lineTo(pts[pts.length - 1].x, padTop + plotH);
          ctx.closePath();
          ctx.fillStyle = bgColor;
          ctx.fill();

          // Stroke line
          ctx.beginPath();
          ctx.strokeStyle = color;
          ctx.lineWidth = ds.borderWidth || 2.5;
          ctx.lineJoin = 'round';
          pts.forEach((p, idx) => {
            if (idx === 0) ctx.moveTo(p.x, p.y);
            else ctx.lineTo(p.x, p.y);
          });
          ctx.stroke();

          // Draw point circles
          pts.forEach(p => {
            ctx.beginPath();
            ctx.arc(p.x, p.y, 4.5, 0, Math.PI * 2);
            ctx.fillStyle = '#ffffff';
            ctx.fill();
            ctx.strokeStyle = color;
            ctx.lineWidth = 2.5;
            ctx.stroke();

            this._points.push(p);
          });
        });
      }

      // Draw Legend at top
      let legX = padLeft;
      const legY = 16;
      ctx.font = '11px sans-serif';
      ctx.textAlign = 'left';

      datasets.forEach(ds => {
        const color = ds.borderColor || ds.backgroundColor || '#3b82f6';
        ctx.fillStyle = color;
        ctx.beginPath();
        ctx.roundRect ? ctx.roundRect(legX, legY - 8, 12, 10, 2) : ctx.rect(legX, legY - 8, 12, 10);
        ctx.fill();

        ctx.fillStyle = '#334155';
        const txt = ds.label || 'Série';
        ctx.fillText(txt, legX + 16, legY);
        legX += ctx.measureText(txt).width + 32;
      });

      // Draw Active Tooltip
      if (this.activeTooltip) {
        const t = this.activeTooltip;
        const text = `${t.datasetLabel ? t.datasetLabel + ' : ' : ''}${t.value}`;
        const sub = t.label || '';

        ctx.font = 'bold 12px sans-serif';
        const tw = Math.max(ctx.measureText(text).width, ctx.measureText(sub).width) + 20;
        const th = 42;
        let bx = t.x - tw / 2;
        let by = t.y - th - 10;

        if (bx < 5) bx = 5;
        if (bx + tw > w - 5) bx = w - tw - 5;
        if (by < 5) by = t.y + 12;

        ctx.fillStyle = 'rgba(15, 23, 42, 0.9)';
        ctx.beginPath();
        ctx.roundRect ? ctx.roundRect(bx, by, tw, th, 6) : ctx.rect(bx, by, tw, th);
        ctx.fill();

        ctx.fillStyle = '#94a3b8';
        ctx.font = '10px sans-serif';
        ctx.textAlign = 'center';
        ctx.fillText(sub, bx + tw / 2, by + 15);

        ctx.fillStyle = '#ffffff';
        ctx.font = 'bold 12px sans-serif';
        ctx.fillText(text, bx + tw / 2, by + 32);
      }
    }
  }

  return Chart;
}));
